"""Metadata processing for report-ledger."""

import json
import datetime


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(str(exc)) from exc

    if not isinstance(data, list):
        raise ValueError("input must be a JSON array")

    total_cents = 0
    first_day = None
    last_day = None

    for row in data:
        if not isinstance(row, dict):
            raise ValueError("each row must be an object")

        # Validate tenant
        tenant = row.get("tenant")
        if not isinstance(tenant, str) or not tenant:
            raise ValueError("tenant must be a nonempty string")

        # Validate amount_cents: must be int, not bool
        amount_cents = row.get("amount_cents")
        if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
            raise ValueError("amount_cents must be an integer")

        # Validate day: must be a valid YYYY-MM-DD string
        day = row.get("day")
        if not isinstance(day, str):
            raise ValueError("day must be a string")
        try:
            parsed = datetime.date.fromisoformat(day)
        except ValueError:
            raise ValueError(f"invalid date: {day}")
        # Reject non-standard ISO formats that fromisoformat might accept
        if day != parsed.strftime("%Y-%m-%d"):
            raise ValueError(f"day must be YYYY-MM-DD: {day}")

        total_cents += amount_cents
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day

    return {
        "row_count": len(data),
        "total_cents": total_cents,
        "first_day": first_day,
        "last_day": last_day,
    }
